aH7(a,b,c){var s=null,r=A.aw(a,s,this.a,s,"round","rounds",s,s)
return"The last "+A.v(c)+" months hold "+a+" "+r+" \u2014 under the floor of "+b+", so every trait reads \u2014 there."},
